/**
 * 将更新日志的原始字符串数组转换为带有格式代码的字符串数组
 * - 三级标题 "### XXX" -> "§lXXX"
 * - 分割线 "---" -> "----------"
 * - 行内代码块 `XXX` -> "§bXXX§r"
 * - 其他正文保持不变
 *
 * 代码由 Deepseek 生成 =P
 */
function formatUpdateLog(lines) {
    return lines.map(line => {
        let result = line;
        // 1. 处理三级标题（行首可能带有缩进，但通常无缩进）
        const headingMatch = result.match(/^###\s+(.*)/);
        if (headingMatch)
            result = "§l" + headingMatch[1];
        // 2. 处理分割线（允许前后有空格）
        else if (result.trim() === "---")
            result = "----------";
        // 3. 处理行内代码块（在标题或正文中均可）
        result = result.replace(/`([^`]*)`/g, "§b$1§r");
        return result;
    });
}
/** 更新日志。 */
export const updateLog = formatUpdateLog(updateLogRaw);
